export const MAP_W = 1000;
export const MAP_H = 400;
export const MAP_K = 1155.2700032433738;
export const MAP_TX = -1889.34693877551;
export const MAP_TY = 144.8437810256193;
/** Proyeksi Mercator yang sama dengan pembuatan path. */
export function project(lon: number, lat: number): [number, number] {
  const x = MAP_K * ((lon * Math.PI) / 180) + MAP_TX;
  const y = MAP_TY - MAP_K * Math.log(Math.tan(Math.PI / 4 + ((lat * Math.PI) / 180) / 2));
  return [Math.round(x * 10) / 10, Math.round(y * 10) / 10];
}
